# Ton application interroge SON sidecar Dapr (port 3500 par defaut).
# On demande explicitement deux cles au config store nomme "configstore".

curl "http://localhost:3500/v1.0-alpha1/configuration/configstore?key=feature-x&key=seuil-alerte"

# Reponse typique : chaque cle porte sa valeur et sa version.
# {
#   "feature-x":    { "value": "true", "version": "1" },
#   "seuil-alerte": { "value": "80",   "version": "3" }
# }

# Sans aucun ?key=..., Dapr renvoie TOUTE la configuration du store.
curl "http://localhost:3500/v1.0-alpha1/configuration/configstore"
